package com.parevetimer.app;
import android.app.Activity;import android.os.Bundle;import android.widget.*;import android.content.Intent;
public class SettingsActivity extends Activity{protected boolean onboardingMode(){return false;} @Override protected void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_settings);EditText bh=findViewById(R.id.beef_hours),bm=findViewById(R.id.beef_minutes),dh=findViewById(R.id.dairy_hours),dm=findViewById(R.id.dairy_minutes);long beef=Prefs.getBeefMs(this),dairy=Prefs.getDairyMs(this);setv(bh,beef/3600000L);setv(bm,(beef/60000L)%60);setv(dh,dairy/3600000L);setv(dm,(dairy/60000L)%60);RadioGroup g=findViewById(R.id.notification_group);String mode=Prefs.getNotificationMode(this);g.check("vibrate".equals(mode)?R.id.radio_vibrate:"custom1".equals(mode)?R.id.radio_custom1:"custom2".equals(mode)?R.id.radio_custom2:R.id.radio_system);findViewById(R.id.save_button).setOnClickListener(v->{long bms=parse(bh,bm),dms=parse(dh,dm);if(bms<=0||dms<0){Toast.makeText(this,"נא להזין זמן תקין",Toast.LENGTH_SHORT).show();return;}String selected=g.getCheckedRadioButtonId()==R.id.radio_vibrate?"vibrate":g.getCheckedRadioButtonId()==R.id.radio_custom1?"custom1":g.getCheckedRadioButtonId()==R.id.radio_custom2?"custom2":"system";Prefs.setTimes(this,bms,dms);Prefs.get(this).edit().putString("notification_mode",selected).putBoolean("onboarded",true).apply();Toast.makeText(this,"ההגדרות נשמרו",Toast.LENGTH_SHORT).show();if(onboardingMode()){startActivity(new Intent(this,MainActivity.class));finish();}else finish();});if(onboardingMode()){((TextView)findViewById(R.id.settings_title)).setText("בואו נגדיר את ההמתנה");((TextView)findViewById(R.id.settings_intro)).setText("זה לוקח רגע — אחר כך לחיצה אחת תפעיל את הטיימר");}}
 private void setv(EditText e,long n){e.setText(String.valueOf(n));e.setSelection(e.length());} private long parse(EditText h,EditText m){try{int hh=h.getText().toString().trim().isEmpty()?0:Integer.parseInt(h.getText().toString().trim());int mm=m.getText().toString().trim().isEmpty()?0:Integer.parseInt(m.getText().toString().trim());if(hh<0||mm<0||mm>59)return -1;return(hh*60L+mm)*60000L;}catch(Exception e){return -1;}}
}